import json
import re
import time
import requests
from typing import Optional, Dict, Any
import logging


class TenderModel:
    """
    大模型调用方法
    get_result：调用主方法
    """
    # 正式服务器
    def __init__(self, base_url: str = 'https://www.51qqx.com/extract/askTender', timeout: int = 30):

        self.url = base_url
        self.timeout = timeout
        self.headers = {
            'Content-Type': 'application/json',
            'Accept': 'application/json',
            'X-Test-Version': "v2",
            # 正式服务器
            "Custom-Token":'FACBED0693D0F2361DED36C4BDF35E19',
        }

        logging.basicConfig(level=logging.INFO)
        self.logger = logging.getLogger(__name__)

    def get_result(self, content: str, max_retries: int = 3) -> Optional[Dict[str, Any]]:
        data = {'text': content,
                "model": "qwen-doc-turbo"
                }

        for attempt in range(max_retries):
            try:

                response = requests.post(
                    self.url,
                    json=data,
                    headers=self.headers,
                    timeout=self.timeout
                )

                response.raise_for_status()  # 检查HTTP错误

                result = self._clear_data(response.json())
                result_dict = self.deal_result(result)
                return result_dict

            except requests.exceptions.RequestException as e:
                self.logger.warning(f"请求失败 (尝试 {attempt + 1}/{max_retries}): {e}")
                if attempt < max_retries - 1:
                    wait_time = 2 ** attempt  # 指数退避
                    self.logger.info(f"等待 {wait_time} 秒后重试...")
                    time.sleep(wait_time)
                else:
                    self.logger.error(f"所有 {max_retries} 次尝试都失败了")
                    return ""
            except Exception as e:
                self.logger.error(f"处理响应时发生错误: {e}")
                return ""

        return ""

    # 调整格式，转换字段
    def deal_result(self,item):
        output_data = {
            'tenderTitle': item.get('项目名称', ''),
            'tenderNumber': item.get('项目编号', ''),
            'procurementUnit': item.get('采购人名称', ''),
            # 'unitAddress': item.get('采购人地址', ''),
            'result': [],
            'execution_time': item.get('execution_time', 0),
            'has_difficulty': item.get('has_difficulty', False),
            'difficult_fields': item.get('difficult_fields', [])
        }
        for itm in item.get('采购结果', []):
            transformed_item = {
                'relationCompanyName': itm.get('供应商名称', ''),
                'contactName': itm.get('联系人姓名', ''),
                'contactTelephone': itm.get('联系人电话', ''),
                'renderMoney': itm.get('中标金额', '')
            }
            output_data['result'].append(transformed_item)

        return output_data


    # 提取字段
    def _clear_data(self, response_data: Dict[str, Any]) -> Optional[Dict[str, Any]]:

        try:
            print(f'模型响应的数据：{response_data}')
            if 'final_result' in response_data:
                content = response_data.get('final_result', '')
            else:
                content = response_data['result']
            return content

        except json.JSONDecodeError as e:
            self.logger.error(f"JSON解析错误: {e}")
            self.logger.debug(f"原始内容: {content}")
            return ""
        except KeyError as e:
            self.logger.error(f"响应数据中缺少必要的键: {e}")
            return ""
        except Exception as e:
            self.logger.error(f"清理数据时发生未知错误: {e}")
            return ""


